insert into public.content_entries (type, slug, title, status, locale, payload, seo)
values
  ('proof_card', 'ddc-rust-test', 'Rust-and-scale removal', 'published', 'en', '{"kind":"hvac","chips":["VertKleen HCR"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/ddc-rust.webp?v=20260617b","result":"VertKleen HCR cut through heavy rust and mineral scale, revealing a dramatically cleaner metal surface.","source":"Source: field record","eyebrow":"HVAC & Water · Result","image_h":579,"image_w":1200,"image_alt":"Metal surface after VertKleen HCR rust-and-scale removal","narrative":"Heavy rust and mineral scale covered the metal. HCR worked underneath the buildup, broke it free, and exposed the dramatically cleaner surface shown in the result.","sort_order":1,"publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'brewery-cip-trials', 'CR + HCR brewery CIP results', 'published', 'en', '{"kind":"food","chips":["VertKleen CR + HCR"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/brewery.webp?v=20260617b","result":"VertKleen CR and HCR replaced caustic and mineral acid while removing organics, beer stone, rust, and scale across brewery equipment.","source":"Source: laboratory and field records","eyebrow":"Food & Beverage · CIP result","image_h":900,"image_w":1200,"image_alt":"Brewery tank and heat exchanger cleaned with VertKleen CR and HCR","narrative":"CR removed yeast, protein, fat, and organic film first. HCR followed with beer stone, scale, and rust. Together, they gave brewery crews one repeatable two-step CIP cycle.","sort_order":2,"publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'distribution-center-assessment', 'Distribution-center equipment degreasing', 'published', 'en', '{"kind":"distribution","chips":["VertKleen CR HD","Customer assessment"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/industries/distribution-cold-storage/g1.webp","result":"Three Walmart distribution centers switched to VertKleen CR HD for heavy-equipment grease and mixed facility cleaning.","source":"Source: customer assessment","eyebrow":"Distribution · Assessment","image_h":1200,"image_w":1600,"image_alt":"Material-handling equipment during a VertKleen CR HD assessment","narrative":"CR HD gave crews one strong concentrate for greasy equipment, floors, parts, kitchens, and other hard warehouse jobs. The switch simplified the chemical shelf without giving up cleaning power.","sort_order":3,"publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'yellowfin-torque-wash', 'Vessel wash and finish', 'published', 'en', '{"kind":"marine","chips":["VertKleen Torque"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/marine.webp?v=20260617b","result":"VertKleen Torque cleaned and finished a working vessel in one wash, leaving a polished marine surface.","source":"Source: field record","eyebrow":"Marine · Result","image_h":1125,"image_w":1175,"image_alt":"Marine vessel after VertKleen Torque wash","narrative":"Road film, salt, and marine grime had dulled the vessel. Torque released the film during the wash and left a clean, glossy finish after rinse.","sort_order":4,"publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'uf-shands-drone-wash', 'Drone-applied exterior cleaning', 'published', 'en', '{"kind":"facility","chips":["VertKleen MultiWash"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/drone-before.webp?v=20260617b","result":"VertKleen MultiWash removed exterior buildup by drone, cleaning a large elevated facility surface with speed and visible impact.","source":"Source: field record","eyebrow":"Drone cleaning · Result","image_h":803,"image_w":1200,"image_alt":"Facility exterior before drone-applied MultiWash cleaning","narrative":"Buildup covered the tall exterior surface. A drone applied MultiWash across the facade, and the before-and-after frames show a much cleaner result without putting a crew on the wall.","sort_order":5,"image_after":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/drone-after.webp?v=20260617b","image_after_h":1029,"image_after_w":1200,"image_after_alt":"Facility exterior after drone-applied MultiWash cleaning","publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'neatfreaks-hood-degrease', 'Restaurant hood and floor degreasing', 'published', 'en', '{"kind":"food","chips":["VertKleen CR + CR HD"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/hood-before.webp?v=20260617b","result":"VertKleen CR and CR HD stripped heavy grease from restaurant hood filters and floors, leaving a visibly cleaner kitchen.","source":"Source: field record","eyebrow":"Food service · Result","image_h":650,"image_w":520,"image_alt":"Restaurant hood filter before VertKleen degreasing","narrative":"Heavy grease loaded the hood filters and floor. CR and CR HD cut through the buildup and lifted it away, producing a clear before-and-after change across the food-service surfaces.","sort_order":6,"image_after":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/hood-after.webp?v=20260617b","image_after_h":650,"image_after_w":520,"image_after_alt":"Restaurant hood filter after VertKleen degreasing","publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'fire-pump-descaler', 'Fire-system component descaling', 'published', 'en', '{"kind":"facility","chips":["VertKleen Descaler"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/fire-pump.webp?v=20260617b","result":"VertKleen Descaler cleared mineral buildup from a fire-system component without the handling burden of hydrochloric acid.","source":"Source: field record","eyebrow":"Fire systems · Result","image_h":681,"image_w":681,"image_alt":"Fire-system component after VertKleen descaling","narrative":"Mineral buildup covered the component. Descaler broke the buildup free and rinsed away, leaving a visibly cleaner surface after the cycle.","sort_order":7,"publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'residential-ac-coil', 'Residential AC coil restoration', 'published', 'en', '{"kind":"hvac","chips":["VertKleen Descaler"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/ac-coil.webp?v=20260617b","result":"VertKleen Descaler removed stubborn buildup from a residential AC coil and restored a visibly cleaner heat-transfer surface.","source":"Source: field record","eyebrow":"Residential HVAC · Result","image_h":471,"image_w":839,"image_alt":"Residential AC coil after VertKleen cleaning","narrative":"Buildup had packed the coil and fin surface. Descaler worked into the fin pack, loosened the buildup, and rinsed away to reveal a visibly cleaner coil.","sort_order":8,"publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'airboat-alumibrite', 'Marine aluminum restoration', 'published', 'en', '{"kind":"marine","chips":["AlumiBrite + Torque"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/airboat-before.webp?v=20260617b","result":"AlumiBrite stripped dull oxidation from the aluminum. Torque followed with a one-step wash and polished finish.","source":"Source: field record","eyebrow":"Marine · Result","image_h":619,"image_w":682,"image_alt":"Aluminum vessel before the VertKleen restoration","narrative":"Weather and oxidation had left the aluminum dull and tired. AlumiBrite brought back the bright metal, then Torque washed away the remaining film and left the vessel clean and polished.","sort_order":9,"image_after":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/airboat-after.webp?v=20260617b","image_after_h":857,"image_after_w":817,"image_after_alt":"Brighter aluminum vessel after the VertKleen restoration","publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'brevard-farm-hvac', 'HVAC rust and scale restoration', 'published', 'en', '{"kind":"hvac","chips":["VertKleen HCR"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/farm-rust-before.webp?v=20260617b","result":"VertKleen HCR removed stubborn rust and mineral scale from HVAC metal and diamond plate without conventional acid.","source":"Source: field record","eyebrow":"HVAC & Water · Result","image_h":844,"image_w":1057,"image_alt":"HVAC metal and diamond plate before HCR cleaning","narrative":"Rust and scale covered the HVAC metal and diamond plate. HCR broke the buildup free and rinsed away, leaving the surfaces visibly cleaner with one straightforward descaling method.","sort_order":10,"image_after":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/farm-rust-after.webp?v=20260617b","image_after_h":967,"image_after_w":740,"image_after_alt":"HVAC metal and diamond plate after HCR cleaning","publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'property-grout-moss', 'Property-surface restoration', 'published', 'en', '{"kind":"facility","chips":["VertKleen CR + LAM3"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/grout-before.webp?v=20260617b","result":"VertKleen CR and LAM3 lifted embedded grime, biological buildup, and grout staining for a dramatic property-cleaning result.","source":"Source: field record","eyebrow":"Property · Result","image_h":700,"image_w":934,"image_alt":"Property surface before VertKleen cleaning","narrative":"Embedded grime, outdoor growth, and dark grout stains marked the property. CR lifted the ground-in grime while LAM3 stayed on the outdoor buildup longer, revealing cleaner hardscape and grout.","sort_order":11,"image_after":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/grout-after.webp?v=20260617b","image_after_h":882,"image_after_w":850,"image_after_alt":"Property surface after VertKleen cleaning","publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'commercial-kitchen-crhd', 'Commercial-kitchen grease removal', 'published', 'en', '{"kind":"food","chips":["VertKleen CR HD"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/kitchen-before.webp?v=20260617b","result":"VertKleen CR HD broke through baked-on commercial-kitchen grease and restored a visibly cleaner working surface.","source":"Source: field record","eyebrow":"Food service · Result","image_h":852,"image_w":917,"image_alt":"Commercial-kitchen surface before CR HD cleaning","narrative":"Baked-on grease covered the working surface. CR HD cut underneath it, lifted it free, and exposed a visibly cleaner kitchen area in the before-and-after result.","sort_order":12,"image_after":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/proof/cases/kitchen-after.webp?v=20260617b","image_after_h":900,"image_after_w":1200,"image_after_alt":"Commercial-kitchen surface after CR HD cleaning","publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'cr-caustic-replacement', 'VertKleen CIP CR replaces caustic', 'published', 'en', '{"kind":"food","chips":["VertKleen CIP CR","Caustic replacement"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/products/cip-cr-studio.webp","result":"VertKleen CIP CR directly replaces caustic in brewery CIP cleaning.","source":"Source: product record","eyebrow":"VertKleen CIP CR · Equivalency","image_h":1200,"image_w":900,"image_alt":"VertKleen CIP CR product","narrative":"Share the current caustic concentration and cycle. MASEST will match a practical starting CR dose and a side-by-side plan for the brewery job.","sort_order":13,"publication_scope":"Published product record"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'cr2-caustic-replacement', 'VertKleen HVAC CR replaces 60% caustic', 'published', 'en', '{"kind":"hvac","chips":["VertKleen HVAC CR","60% sodium hydroxide replacement"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/products/hvac-cr-studio.webp","result":"VertKleen HVAC CR directly replaces 60% sodium hydroxide for HVAC and facility cleaning jobs.","source":"Source: product record","eyebrow":"VertKleen HVAC CR · Equivalency","image_h":1200,"image_w":900,"image_alt":"VertKleen HVAC CR product","narrative":"Share the current concentration, surface, and buildup. MASEST will map HVAC CR to the job and give the crew a clear starting method.","sort_order":14,"publication_scope":"Published product record"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'watersafe60-nsf60', 'WaterSafe60 NSF/ANSI/CAN 60 certification', 'published', 'en', '{"kind":"hvac","chips":["WaterSafe60","NSF/ANSI/CAN 60"],"image":"https://mvfxzvkzcqmnwcoblvfc.supabase.co/storage/v1/object/public/content-assets/site/img/products/watersafe60-studio.webp","result":"WaterSafe60 is NSF/ANSI/CAN 60 certified for lowering potable-water pH, well rehabilitation, corrosion and scale control, and pipe cleaning.","source":"Source: product record","eyebrow":"WaterSafe60 · Certification","image_h":1200,"image_w":900,"image_alt":"WaterSafe60 product","narrative":"Share the system use, volume, materials, and water data. MASEST will provide the certification details and a practical starting plan for the system.","sort_order":15,"publication_scope":"Published product record"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'sportfisher-raw-water-intake', 'Sportfisher raw-water intake descaling', 'published', 'en', '{"kind":"marine","chips":["Scale Buster","1:1 mix","24-hour soak","No scrubbing"],"image":"img/proof/cases/sportfisher-intake-before-202608.webp","result":"On one 68-foot sportfisher field record, a raw-water intake grate received a 1:1 Scale Buster mix for a 24-hour soak. No scrubbing or scraping was used before rinse; the published before-and-after photos show the perforations after rinsing.","source":"Source: documented field record, August 2026","eyebrow":"Marine · Result","image_h":820,"image_w":1200,"image_alt":"Sportfisher raw-water intake grate before Scale Buster treatment","narrative":"This result records a single August 2026 cleaning of one raw-water intake grate. Scale Buster is a cleaner, not an antifouling coating, and leaves no protective film. Results vary with deposit type, thickness, water chemistry, dilution, and dwell time. Verify material compatibility and disposal requirements before use.","sort_order":16,"image_after":"img/proof/cases/sportfisher-intake-after-202608.webp","image_after_h":820,"image_after_w":1200,"image_after_alt":"Sportfisher raw-water intake grate after Scale Buster treatment and rinse","publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'cip-vessel', 'CIP vessel residue removal', 'published', 'en', '{"kind":"food","chips":["VertKleen CR","CIP circuit","Aligned before and after"],"image":"/img/proof/story/cip-vessel-before-aligned-202609.webp","result":"Same vessel geometry: CR removes the organic residue field and returns the interior to reflective steel. The before and after frames are photographed from one fixed camera position so the surface can be compared directly.","source":"Source: registered field comparison record","eyebrow":"Food & beverage · Result","image_h":1017,"image_w":1200,"image_alt":"CIP vessel before VertKleen CR cleaning","narrative":"This record covers one CIP vessel cleaned with VertKleen CR. Results vary with soil type and load, vessel material, dilution, temperature, circulation time, and rinse. Read the current label and SDS, confirm material compatibility, and follow the sanitation program in force at the site; a cleaner does not replace an approved sanitation step.","sort_order":17,"image_after":"/img/proof/story/cip-vessel-after-aligned-202609.webp","image_after_h":1017,"image_after_w":1200,"image_after_alt":"Same CIP vessel after VertKleen CR cleaning","publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'labelle-fermenter', 'LaBelle fermenter ring removal', 'published', 'en', '{"kind":"food","chips":["VertKleen CR","Fermenter interior","Aligned before and after"],"image":"/img/proof/story/labelle-fermenter-before-aligned-202609.webp","result":"Geometry stays recognizable: the vessel curve and port remain fixed while the brown ring disappears. The pair is registered to the same camera position so the ring line can be compared directly.","source":"Source: registered field comparison record","eyebrow":"Food & beverage · Result","image_h":1017,"image_w":1200,"image_alt":"LaBelle fermenter wall ring before VertKleen CR cleaning","narrative":"This record covers one fermenter cleaned with VertKleen CR. Results vary with residue age and thickness, vessel material, dilution, temperature, contact time, and rinse. Read the current label and SDS, confirm material compatibility, and complete the required sanitation steps after cleaning.","sort_order":18,"image_after":"/img/proof/story/labelle-fermenter-after-aligned-202609.webp","image_after_h":1017,"image_after_w":1200,"image_after_alt":"Same LaBelle fermenter after VertKleen CR cleaning","publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'shower-track', 'Shower track calcium removal', 'published', 'en', '{"kind":"facility","chips":["VertKleen Descaler","Glass and track","Aligned before and after"],"image":"/img/proof/story/shower-track-before-aligned-202609.webp","result":"The same glass edge and lower track stay aligned while Descaler clears the concentrated orange calcium line. Both frames share one camera position so the track edge can be compared directly.","source":"Source: registered field comparison record","eyebrow":"Facilities · Result","image_h":1017,"image_w":1200,"image_alt":"Shower track before VertKleen Descaler cleaning","narrative":"This record covers one shower track treated with VertKleen Descaler. Results vary with deposit type and thickness, water chemistry, surface finish, dilution, and dwell time. Read the current label and SDS and confirm material compatibility before use, particularly on finished metal and coated surfaces.","sort_order":19,"image_after":"/img/proof/story/shower-track-after-aligned-202609.webp","image_after_h":1017,"image_after_w":1200,"image_after_alt":"Same shower track after VertKleen Descaler cleaning","publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb),
  ('proof_card', 'pool-cartridge', 'Pool cartridge filter descaling', 'published', 'en', '{"kind":"facility","chips":["VertKleen HCR","Cartridge filter","Aligned before and after"],"image":"/img/proof/story/pool-cartridge-before-aligned-202609.webp","result":"The cap, bands, and pleat pattern stay registered while HCR clears the dark mineral fouling. The pair is photographed from one fixed position so the pleat field can be compared directly.","source":"Source: registered field comparison record","eyebrow":"Facilities · Result","image_h":1017,"image_w":1200,"image_alt":"Pool cartridge filter before VertKleen HCR cleaning","narrative":"This record covers one pool cartridge filter cleaned with VertKleen HCR. Results vary with fouling type and age, cartridge material and condition, water chemistry, dilution, and soak time. Read the current label and SDS, confirm material compatibility, and replace cartridges according to the service life stated by the manufacturer.","sort_order":20,"image_after":"/img/proof/story/pool-cartridge-after-aligned-202609.webp","image_after_h":1017,"image_after_w":1200,"image_after_alt":"Same pool cartridge filter after VertKleen HCR cleaning","publication_scope":"Published result summary"}'::jsonb, '{}'::jsonb)
